    "worker": "You are an Executor",
    "reviewer": "You are the release-gate Reviewer",
    "verifier": "You are the L2 Verifier",
    "duty_officer": "You are the Duty Officer",
}


def load_records(path: Path) -> list[dict]:
    records: list[dict] = []
    for line in path.read_text(encoding="utf-8").splitlines():
        try:
            records.append(json.loads(line))
        except json.JSONDecodeError:
            continue
    return records


def session_meta(records: list[dict]) -> dict:
    for record in records:
        if record.get("type") == "session_meta":
            return record.get("payload", {})
    return {}


def message_text(payload: dict) -> str:
    parts: list[str] = []
    for item in payload.get("content", []):
        if isinstance(item, dict) and isinstance(item.get("text"), str):
            parts.append(item["text"])
    return "\n".join(parts)


def structured_role(records: list[dict]) -> str | None:
    """Classify only from the injected developer role message.

    Searching an entire rollout would allow user prompts, tool output, or
    quoted documentation to impersonate a role marker.
    """
    developer_messages = [
        message_text(payload)
        for record in records
        if record.get("type") == "response_item"
        and (payload := record.get("payload", {})).get("type") == "message"
        and payload.get("role") == "developer"
